import csv, re
from collections import Counter
rows=list(csv.DictReader(open('documents/bank_checking_2024-12_to_2026-01.csv')))
def amt(r): return float(r['amount'])
print("rows", len(rows), "sum", round(sum(amt(r) for r in rows),2))
old=list(csv.DictReader(open('deliverable/classification.csv')))
print("dist", Counter(r['classification'] for r in old))
mismatch=[(b,c) for b,c in zip(rows,old) if (b['date'],b['description'],b['amount'])!=(c['date'],c['description'],c['amount'])]
print("row-identity mismatches:", len(mismatch))
for m in mismatch[:10]: print("  MISMATCH", m)
def show(pat, label):
    sel=[r for r in rows if re.search(pat, r['description'], re.I)]
    print(f"--- {label}: n={len(sel)} sum={round(sum(amt(r) for r in sel),2)}")
    for r in sel: print("   ", r['date'], r['description'], r['amount'])
show(r'PAYHUB','PAYHUB'); show(r'TESSARO','TESSARO'); show(r'LARKSPUR','LARKSPUR')
show(r'CAPITAL FACTORY|COWORK','COWORK'); show(r'BCBS|BLUE CROSS','BCBS'); show(r'RENT','RENT')
show(r'USATAXPYMT|IRS','IRS-ES'); show(r'TRANSFER','TRANSFER'); show(r'HISCOX','HISCOX')
show(r'APPLE','APPLE'); show(r'ADOBE|FIGMA','SOFTWARE'); show(r'SOUTHWEST|HOTEL|DESIGNWEEK|ZEPHYR','TRAVEL')
show(r'DELI|TARTINE|RESTAURANT|CAFE|DINER|PANDA|CHIPOTLE|TAQUERIA|PIZZA','FOOD')
print("--- prior_year rows in classification:")
for r in old:
    if r['classification']=='prior_year': print("   ", r['date'], r['description'], r['amount'])
print("--- pre-2025 bank rows:")
for r in rows:
    if r['date']<'2025': print("   ", r['date'], r['description'], r['amount'])
EOF","timeout":120000}

